-- Correct Course 2 Lesson 5: distinguish ezafe with adjectives from possessive ezafe.
-- Haig (2018), §2.3.1, examples (4) and (5), and NP order Dem Num N-Ez Poss Ez Adj.
DO $migration$
DECLARE affected integer;
BEGIN
  UPDATE public.lesson_content
  SET title = 'ئەزافە و پەیوەندیی ناو و هاوەڵناو',
      content_html = $new$<section class="klesson-card"><h2>١. پێکهاتەی ناو و هاوەڵناو</h2><p>لە کورمانجیی ستاندارددا هاوەڵناو دەتوانێت بە ڕێگای ئەزافەوە بە ناوی سەرەکییەوە ببەسترێتەوە. ڕیزبەندیی بنەڕەتیی پێکهاتەی ناو، ئەگەر خاوەندار و هاوەڵناو هەردووکیان هەبن، ئەوەیە: ناو، پاشان خاوەندار، و دواتر هاوەڵناو. ئەم ڕیزبەندییە لە هەموو پێکهاتەکاندا نابێت بە یاسایەکی بێ‌مەرج تێبگەین؛ دیارخەر و ژمارەش دەتوانن کاریگەرییان هەبێت.</p><p>نموونەی <em>bajar-ek-î mezin</em> «شارێکی گەورە» (Haig, 2018، §2.3.1، نموونەی 4) پێکهاتەی ناو + نیشانەی نادیاری + ئەزافە + هاوەڵناو نیشان دەدات. لێرەدا <em>-ek</em> نادیاریی ناوەکە نیشان دەدات، <em>-î</em> پەیوەندیی ئەزافەیە، و <em>mezin</em> هاوەڵناوەکەیە.</p></section><section class="klesson-card"><h2>٢. ئەزافە لەگەڵ خاوەندار</h2><p>ئەزافە دەتوانێت ناوی سەرەکی بە خاوەندارەوە ببەستێتەوە. لە نموونەی <em>mal-a me</em> «ماڵی ئێمە» (Haig, 2018، §2.3.1، نموونەی 5)، <em>mal</em> ناوی سەرەکییە، <em>-a</em> نیشانەی ئەزافەیە، و <em>me</em> فۆڕمی ناڕاستەوخۆی جێناوی کەسییە کە لێرەدا وەک خاوەندار هاتووە. ئەم نموونەیە لە نموونەی هاوەڵناودار جیاوازە و نابێت تێکەڵ بکرێن.</p></section><section class="klesson-card"><h2>٣. جیاکردنەوەی پێکهاتەکان</h2><ul><li><em>bajar-ek-î mezin</em>: ناو + نیشانەی نادیاری + ئەزافە + هاوەڵناو.</li><li><em>mal-a me</em>: ناو + ئەزافە + خاوەندار.</li></ul><p>فۆڕمی ئەزافە بە ڕەگەز و ژمارەی ناوی سەرەکی پەیوەستە. بۆیە لە شیکردنەوەدا سەرەتا ناوی سەرەکی دیاری بکە، پاشان نیشانەی ئەزافە و ئەو پێکهاتەیەی دوای ئەوە دێت بناسەوە.</p></section><section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">Haig (2018)، §2.3.1، ڕیزبەندیی پێکهاتەی ناوی بە شێوەی Dem Num N-Ez Poss Ez Adj باس دەکات؛ واتە دیارخەر، ژمارە، ناو، خاوەندار و هاوەڵناو بە پەیوەندیی ئەزافە. نموونەکانی <em>bajar-ek-î mezin</em> و <em>mal-a me</em> لێرەدا بە جیاوازی پێشکەش کراون بۆ ئەوەی فۆڕمی هاوەڵناو لە فۆڕمی خاوەنداری تێکەڵ نەکرێت. جیاوازیی شێوەزارەکان دەبێت بە سەرچاوەی تایبەت بپشکنرێت.</p></section><section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>لە <em>bajar-ek-î mezin</em>، <em>-ek</em> و <em>-î</em> هەر یەکەیان چی نیشان دەدەن؟</li><li>لە <em>mal-a me</em>، <em>me</em> چ ئەرکێکی ڕێزمانی هەیە؟</li><li>ئەگەر خاوەندار و هاوەڵناو هەردووکیان لە پێکهاتەیەکدا بن، بە گشتی خاوەندار لە کوێ دێت؟</li></ol></section><section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">ناوەڕۆکەکە لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراوە؛ بۆ فۆڕمی ناوچەیی، سەرچاوە و سیاقی تایبەت پێویستە.</p></section>$new$,
      updated_at = now()
  WHERE lesson_key = 'kurmanji-course-2-lesson-05.html'
    AND course_id = 'kurmanji-course-2'
    AND content_html = $old$<section class="klesson-card"><h2>١. ئەزافە لەگەڵ هاوەڵناو</h2><p>هاوەڵناو زۆرجار دوای ناو دێت و بە ئەزافەوە بە ناوەکەوە دەبەسترێتەوە. نمونەی نووسراو لە Geoffrey Haig (2018): bajar-ek-î mezin ‘شارێکی گەورە’. ئەم نمونەیە نادیاری، ئەزافە و هاوەڵناو لە یەک پێکهاتەدا نیشان دەدات.</p></section><section class="klesson-card"><h2>٢. ئەزافە لەگەڵ خاوەندار</h2><p>ئەزافە بۆ پەیوەستکردنی ناو بە خاوەندار یان ناوی دیکەش بەکاردێت. فۆڕمی ئەزافە بە ڕەگەز و ژمارەی ناوی سەرەکی پەیوەستە، بەڵام لە ناوی نادیاری پاشگری <em>-ek</em> هەندێک جیاوازی و ناڕێکیی فۆڕمەکان هەیە. لە <em>bajar-ek-î mezin</em>، <em>-ek</em> نادیاری نیشان دەدات، <em>-î</em> ئەزافەی ناوی نێرە، و <em>mezin</em> هاوەڵناوەکەیە و لە ئەزافەدا ناگۆڕێت. لە پێکهاتەی خاوەنداریش، خاوەندار بە فۆڕمی ناڕاستەوخۆ دێت؛ بۆیە پەیویستە خاوەندار، سەرەناو و هاوەڵناو لە یەکتر جیا بکرێنەوە.</p></section><section class="klesson-card"><h2>٣. ڕیزبەندیی پێکهاتە</h2><p>لە پێکهاتەی ناویی کورمانجی‌دا ناو دەتوانێت لەگەڵ دیارخەر، ژمارە، خاوەندار و هاوەڵناو بێت. ڕیزبەندی و فۆڕمی ئەزافە بە پێکهاتەی وردەوە دەگۆڕێت؛ نابێت یاسایەکی سادە بۆ هەمو پێکهاتەکان بەکاربهێنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">نمونەی bajar-ek-î mezin لە بەشی Geoffrey Haig (2018)، §2.3.1، نمونەی (4) هاتووە. فۆڕمەکانی ئەزافە لە شێوەزارەکاندا هەندێک جیاوازییان هەیە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ئەزافە چ ئەرکێکی ڕێزمانی هەیە؟</li><li>بۆچی فۆڕمی ئەزافە بە ناوی سەرەکی پەیوەستە؟</li><li>لە نمونەی bajar-ek-î mezin، -î چی پەیوەندییەک دروست دەکات؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>$old$;

  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Expected exactly one unchanged Course 2 Lesson 5 row; updated % rows', affected;
  END IF;
END
$migration$;
